const DEFAULTS = {
  rev: 'personal-gtm-sprint1-unified',
  enabled: true,
  max_companies_per_run: 25,
  min_account_score: 65,
  priority_score: 80,
  allow_agencies: true,
  allow_startups: true,
  allow_smb: true,
  allow_enterprise: false,
  timezone: {
    allowed_utc_offsets: [0, 1, 2, 3, 4],
    allow_unknown_timezone: false
  },
  company: {
    employee_min: 2,
    employee_max: 150,
    must_have_domain: true,
    industries_include: [],
    industries_exclude: [],
    keywords_include: [],
    keywords_exclude: []
  },
  scoring: {
    weights: {
      icp_fit: 0.35,
      budget_proxy: 0.25,
      automation_need: 0.25,
      timezone_fit: 0.15
    },
    vertical_boost: {
      enabled: true,
      bonus: 5,
      keywords: []
    }
  }
};

const rows = $('Fetch Config').all().map(i => i.json);
const row = rows.find(r => String(r.key || '').trim().toLowerCase() === 'config_json');

let warnings = [];
let config = JSON.parse(JSON.stringify(DEFAULTS));

if (row && row.value) {
  try {
    const parsed = typeof row.value === 'string' ? JSON.parse(row.value) : row.value;

    config = {
      ...config,
      ...parsed,
      timezone: {
        ...config.timezone,
        ...(parsed.timezone || {})
      },
      company: {
        ...config.company,
        ...(parsed.company || {})
      },
      scoring: {
        ...config.scoring,
        ...(parsed.scoring || {}),
        weights: {
          ...config.scoring.weights,
          ...((parsed.scoring || {}).weights || {})
        },
        vertical_boost: {
          ...config.scoring.vertical_boost,
          ...((parsed.scoring || {}).vertical_boost || {})
        }
      }
    };
  } catch (e) {
    warnings.push('config_json invalid: ' + String(e.message || e));
  }
} else {
  warnings.push('config_json missing; using defaults');
}

return [{ json: { config, warnings } }];

// Parse Forum Mail (Code node, Run Once for All Items). Sprint 15, Phase 0 outcome.
// The n8n and Make community terms forbid automated access to the forums, so new Jobs topics reach the
// engine as the forum's own notification emails: you set the Jobs category to "Watching First Post", a Gmail
// filter labels those emails, and the Read Forum Mail node reads them. This node turns each email into a post.
// While Read Forum Mail is disabled (no Gmail credential yet), n8n passes the Load Config item through: it is ignored.
const cfg = $('Load Config').first().json.config || {};
const G = cfg.gig || {};
const S = (G.sources || {}).forum_mail || {};
if (G.enabled === false || S.enabled === false) return [{ json: { __skipped: 'forum_mail: disabled by config' } }];

const HOSTS = (Array.isArray(S.hosts) && S.hosts.length ? S.hosts : ['community.n8n.io']).map(h => String(h).toLowerCase());
const PREFIX = { 'community.n8n.io': 'n8n', 'community.make.com': 'make' };
const PLATFORM = { 'community.n8n.io': 'n8n_forum', 'community.make.com': 'make_forum' };
const esc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const LINK = new RegExp('https?://(' + HOSTS.map(esc).join('|') + ')/t/([a-z0-9%_-]+)/(\\d+)(?:/(\\d+))?', 'i');

const htmlText = h => String(h || '')
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|h\d|tr|blockquote)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"')
  .replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const FOOTER = /\n\s*(visit topic|reply to this email|to unsubscribe|you are receiving this|unsubscribe|view in browser|in reply to)\b/i;

const mails = $input.all().map(i => i.json).filter(m => m && (m.id || m.messageId) && (m.subject || m.Subject || m.text || m.html || m.snippet));
if (!mails.length) return [{ json: { __skipped: 'forum_mail: no mail read (Read Forum Mail disabled, no credential, or no new mail)' } }];

const C = { mails: mails.length, posts: 0, no_link: 0, replies_skipped: 0 };
const byKey = new Map();
for (const m of mails) {
  const subject = String(m.subject || m.Subject || '').trim();
  const text = m.text ? String(m.text).replace(/\r/g, '') : htmlText(m.html || m.textAsHtml || m.snippet || '');
  const hay = text + '\n' + String(m.html || '');
  const lm = hay.match(LINK);
  if (!lm) { C.no_link++; continue; }
  const host = lm[1].toLowerCase(), slug = lm[2], topicId = lm[3], postNo = Number(lm[4] || 1);
  if (postNo > 1) { C.replies_skipped++; continue; }                     // a reply in the thread, not a new post

  const fromName = (m.from && m.from.value && m.from.value[0] && m.from.value[0].name) || String(m.From || '').replace(/<[^>]*>/, '').trim();
  const poster = String(fromName || '').replace(/^"|"$/g, '').replace(/\s+via\s+.+$/i, '').trim();
  let title = subject.replace(/^\s*((re|fwd?):\s*)*/i, '').replace(/^(\s*\[[^\]]*\])+\s*/, '').trim();
  if (!title) title = decodeURIComponent(slug).replace(/-/g, ' ');
  let body = text;
  const f = body.search(FOOTER);
  if (f > 40) body = body.slice(0, f);
  body = body.split('\n').filter(l => !LINK.test(l) || l.replace(LINK, '').trim().length > 10).join('\n').trim().slice(0, 4000);

  const date = m.date ? new Date(m.date) : (m.internalDate ? new Date(Number(m.internalDate)) : new Date());
  const post = {
    post_key: (PREFIX[host] || host.split('.')[1] || 'forum') + ':' + topicId,
    platform: PLATFORM[host] || 'n8n_forum',
    url: 'https://' + host + '/t/' + slug + '/' + topicId,
    title: title.slice(0, 300), body_text: body, poster: poster.slice(0, 120), poster_company: '',
    posted_at: isNaN(date.getTime()) ? new Date().toISOString() : date.toISOString(),
    reply_count: null, __source: 'forum_mail'
  };
  const prev = byKey.get(post.post_key);
  if (!prev || post.body_text.length > prev.body_text.length) byKey.set(post.post_key, post);
}
C.posts = byKey.size;
return [...byKey.values()].map(p => ({ json: p })).concat([{ json: { __stats: 'forum_mail: ' + Object.entries(C).map(([k, v]) => k + '=' + v).join(' ') } }]);

// HN Freelancer Source (Code node, Run Once for All Items). Sprint 15.
// Latest "Ask HN: Freelancer? Seeking freelancer?" thread via the public Algolia API; keeps top-level
// comments that start with SEEKING FREELANCER (people hiring). Off by default: the Phase 0 spike found
// 0 hiring posts in the August to November 2026 threads. Turn on with gig.sources.hn_freelancer.enabled.
const cfg = $('Load Config').first().json.config || {};
const G = cfg.gig || {};
const S = (G.sources || {}).hn_freelancer || {};
if (G.enabled === false || S.enabled !== true) return [{ json: { __skipped: 'hn_freelancer: disabled by config' } }];

const TITLE = String(S.title_match || 'Freelancer? Seeking freelancer?');
const http = async (url) => this.helpers.httpRequest({ method: 'GET', url, json: true, timeout: 20000 });
const text = h => String(h || '').replace(/<p>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#x2F;/g, '/').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

let story;
try {
  const s = await http('https://hn.algolia.com/api/v1/search_by_date?tags=story&hitsPerPage=10&query=' + encodeURIComponent('"' + TITLE + '"'));
  const hits = (s.hits || []).filter(h => String(h.title || '').toLowerCase().includes(TITLE.toLowerCase()));
  if (!hits.length) return [{ json: { __error: 'hn_freelancer: no thread found for "' + TITLE + '"' } }];
  // Two people sometimes post the same month: take the latest month, then the busiest thread in it.
  const month = String(hits[0].created_at || '').slice(0, 7);
  story = hits.filter(h => String(h.created_at || '').slice(0, 7) === month).sort((a, b) => (b.num_comments || 0) - (a.num_comments || 0))[0];
} catch (e) { return [{ json: { __error: 'hn_freelancer: search failed: ' + String(e.message || e).slice(0, 80) } }]; }

let item;
try { item = await http('https://hn.algolia.com/api/v1/items/' + story.objectID); }
catch (e) { return [{ json: { __error: 'hn_freelancer: thread fetch failed: ' + String(e.message || e).slice(0, 80) } }]; }

const kids = Array.isArray(item.children) ? item.children : [];
const out = [];
for (const k of kids) {
  const t = text(k.text);
  if (!/^seeking freelancer/i.test(t)) continue;
  const firstLine = t.split('\n')[0].replace(/^seeking freelancer\s*[:|-]?\s*/i, '').trim();
  out.push({ json: {
    post_key: 'hn:' + k.id, platform: 'hn_freelancer', url: 'https://news.ycombinator.com/item?id=' + k.id,
    title: (firstLine || 'SEEKING FREELANCER').slice(0, 300), body_text: t.slice(0, 4000),
    poster: String(k.author || ''), poster_company: '', posted_at: k.created_at || null,
    reply_count: Array.isArray(k.children) ? k.children.length : null, __source: 'hn_freelancer'
  } });
}
return out.concat([{ json: { __stats: 'hn_freelancer: thread=' + story.objectID + ' top_level=' + kids.length + ' hiring=' + out.length } }]);

// Gig Gates (Code node, Run Once for All Items). Sprint 15, ADR-116.
// Normalizes every post from Merge Posts, then runs the fixed gates in plan order, before any LLM call:
// seen, intent, freshness, crowding, veto, stack, budget. Every drop is counted.
// Gated posts keep status gated_out plus gate_reason (they are still upserted, for telemetry and dedupe).
// Seen posts (already drafted, sent, answered or expired) are counted and dropped here.
const cfg = $('Load Config').first().json.config || {};
const G = cfg.gig || {};
const MAX_AGE_H = Number(G.max_age_hours ?? 72);
const MAX_REPLIES = Number(G.max_replies ?? 25);
const MIN_RATE = G.min_hourly_usd === null || G.min_hourly_usd === undefined || G.min_hourly_usd === '' ? null : Number(G.min_hourly_usd);
const VETO = (G.veto_keywords || []).map(s => String(s).toLowerCase()).filter(Boolean);
const STACK_KW = (G.stack_keywords || []).map(s => String(s).toLowerCase()).filter(Boolean);
const MY_STACK = (G.my_stack || []).map(String).filter(Boolean);

const esc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const word = (kw) => new RegExp('(^|[^a-z0-9])' + esc(kw.toLowerCase()) + '([^a-z0-9]|$)', 'i');
const clean = s => String(s == null ? '' : s).replace(/\r/g, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

// ---------- inputs ----------
const sourceNotes = [];
const raw = [];
for (const it of $('Merge Posts').all()) {
  const j = it.json || {};
  if (j.__skipped) { sourceNotes.push(String(j.__skipped)); continue; }
  if (j.__error) { sourceNotes.push('ERROR ' + String(j.__error)); continue; }
  if (j.__stats) { sourceNotes.push(typeof j.__stats === 'string' ? j.__stats : JSON.stringify(j.__stats)); continue; }
  if (j.post_key) raw.push(j);
}
const seen = new Map();
for (const it of $('Fetch Seen Gigs').all()) { const j = it.json || {}; if (j.post_key) seen.set(String(j.post_key), String(j.status || '')); }

// One row per post_key; the longest body wins (a post can arrive by mail and by a manual add).
const byKey = new Map();
for (const r of raw) {
  const k = String(r.post_key).trim();
  const prev = byKey.get(k);
  if (!prev || String(r.body_text || '').length > String(prev.body_text || '').length) byKey.set(k, r);
}

const C = { fetched: byKey.size, already_seen: 0, intent_for_hire: 0, intent_unclear: 0, stale: 0, crowded: 0,
            vetoed: 0, stack_miss: 0, budget_low: 0, passed: 0 };

// ---------- intent (ADR-116) ----------
const TAG_HIRING = /\[(hiring|paid|job|task|gig|hire)\]/i;
const TAG_FOR_HIRE = /\[(for hire|available|offering|seeking work)\]/i;
const FOR_HIRE = /\bfor hire\b|available for (hire|work)|seeking work|open to work|\bi'?m available\b|\bhire me\b|offering my services|my services/i;
const HIRING = /\bhiring\b|looking for|seeking (a |an )?(freelancer|developer|builder|expert|consultant|engineer)|\bneed (an? |help|someone)|\bwanted\b|paid (job|task|trial|project)|\bcontract\b|\bbudget\b|\bwho can\b/i;

// ---------- extractors ----------
const EMAIL = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i;
const DM = /\b(dm|pm) me\b|send me a (dm|pm|message)|direct message|message me|reach out (to me )?(privately|directly)|via dm/i;
const RATE = /(?:\$|usd\s?|us\$)\s?(\d{1,4}(?:\.\d+)?)\s*(?:\/\s?h(?:ou)?r?\b|per hour|an hour|hourly|\/h\b)|(\d{1,4}(?:\.\d+)?)\s?(?:usd|\$)\s*(?:\/\s?h(?:ou)?r?\b|per hour|an hour|hourly)/i;
const BUDGET = /(?:budget|pay|paying|rate|fixed price|price)[^.\n]{0,40}?(?:[$€£]\s?\d[\d,.]*k?|\d[\d,.]*\s?(?:usd|eur|gbp|dollars|euros))|[$€£]\s?\d[\d,.]*k?(?:\s?(?:\/\s?h(?:ou)?r?|per hour|hourly|fixed))?/i;
const REMOTE = /\bremote\b|\basync\b|anywhere|\b(eu|uk|cet|gmt|bst|emea)\b|europe|time ?zone/i;

const out = [];
const nowMs = Date.now();
for (const [k, r] of byKey) {
  const title = clean(r.title).slice(0, 300);
  const body = clean(r.body_text).slice(0, 4000);
  const head = (title + '\n' + body.slice(0, 300));
  const all = (title + '\n' + body).toLowerCase();
  const posted = r.posted_at ? new Date(r.posted_at) : null;
  const ageH = posted && !isNaN(posted.getTime()) ? (nowMs - posted.getTime()) / 3600000 : null;
  const replies = r.reply_count === null || r.reply_count === undefined || r.reply_count === '' ? null : Number(r.reply_count);
  const email = (body.match(EMAIL) || [''])[0];
  const rate = body.match(RATE) || title.match(RATE);
  const rateUsd = rate ? Number(rate[1] || rate[2]) : null;
  const matched = MY_STACK.filter(t => word(t).test(all));
  const stackHits = STACK_KW.filter(t => word(t).test(all));

  const post = {
    post_key: k, platform: r.platform, url: r.url, title, body_text: body,
    poster: clean(r.poster).slice(0, 120), poster_company: clean(r.poster_company).slice(0, 120),
    posted_at: posted && !isNaN(posted.getTime()) ? posted.toISOString() : null,
    reply_count: Number.isFinite(replies) ? replies : null,
    contact_email: email, contact_hint: email ? 'email' : (DM.test(body) ? 'dm_invited' : 'reply'),
    stated_budget: ((body.match(BUDGET) || title.match(BUDGET) || [''])[0]).slice(0, 80),
    remote_hint: ((all.match(REMOTE) || [''])[0]).slice(0, 40),
    matched_stack: matched.join(', '),
    intent: 'unclear', status: 'new', gate_reason: '',
    __age_h: ageH === null ? null : Math.round(ageH * 10) / 10,
    __stack_hits: stackHits.length, __rate_usd: rateUsd, __source: r.__source || r.platform
  };

  // 1. seen: already drafted, sent, answered or expired. Not upserted again.
  const st = seen.get(k);
  if (st) { C.already_seen++; continue; }

  // 2. intent
  if (TAG_HIRING.test(title)) post.intent = 'hiring';
  else if (TAG_FOR_HIRE.test(title) || FOR_HIRE.test(head)) post.intent = 'for_hire';
  else if (HIRING.test(head)) post.intent = 'hiring';
  const gate = (reason, counter) => { post.status = 'gated_out'; post.gate_reason = reason; C[counter]++; };
  if (post.intent === 'for_hire') gate('intent_for_hire', 'intent_for_hire');
  else {
    if (post.intent === 'unclear') C.intent_unclear++;
    // 3. freshness, 4. crowding, 5. veto, 6. stack, 7. budget
    if (ageH !== null && ageH > MAX_AGE_H) gate('stale', 'stale');
    else if (post.reply_count !== null && post.reply_count > MAX_REPLIES) gate('crowded', 'crowded');
    else {
      const v = VETO.find(kw => word(kw).test(all));
      if (v) gate('veto:' + v, 'vetoed');
      else if (!stackHits.length && !matched.length) gate('stack_miss', 'stack_miss');
      else if (MIN_RATE !== null && Number.isFinite(MIN_RATE) && rateUsd !== null && rateUsd < MIN_RATE) gate('budget_low:' + rateUsd, 'budget_low');
    }
  }
  if (post.status === 'new') C.passed++;
  out.push({ json: post });
}

out.push({ json: { __gate_stats: C, __source_notes: sourceNotes.slice(0, 10) } });
return out;

// Score Gigs (Code node, Run Once for All Items). Sprint 15.
// Scores every post that passed Gig Gates (0 to 100, written to score_breakdown) and packs all posts,
// gated ones included, into one item for Upsert Gig Posts. Also hands the draft and expiry parameters on.
//   gig_score = 0.35*stack_fit + 0.20*intent + 0.15*freshness + 0.15*competition + 0.10*budget_signal + 0.05*remote_fit (+10 bonus)
const cfg = $('Load Config').first().json.config || {};
const G = cfg.gig || {};
const T = (cfg.lead_tracks || {}).gig_post || {};
const MIN_RATE = G.min_hourly_usd === null || G.min_hourly_usd === undefined || G.min_hourly_usd === '' ? null : Number(G.min_hourly_usd);

const items = $input.all().map(i => i.json);
const stats = Object.assign({}, (items.find(j => j.__gate_stats) || {}).__gate_stats || {});
const notes = (items.find(j => j.__source_notes) || {}).__source_notes || [];
const posts = items.filter(j => j && j.post_key);

const BONUS = /\bagency\b|our clients|white[- ]label|\bongoing\b|long[- ]term|retainer|more work|future projects/i;
const PAID_TRIAL = /paid (trial|test|task)|trial task/i;

let scored = 0;
const packed = posts.map(p => {
  const row = Object.assign({}, p);
  if (row.status === 'new') {
    const n = String(row.matched_stack || '').split(',').map(s => s.trim()).filter(Boolean).length;
    const stack = n >= 3 ? 100 : n === 2 ? 75 : n === 1 ? 50 : 25;           // 25: passed on a stack keyword only
    const intent = row.intent === 'hiring' ? 100 : 40;
    const age = row.__age_h;
    const fresh = age === null ? 50 : age < 12 ? 100 : age < 24 ? 80 : age < 48 ? 50 : 20;
    const r = row.reply_count;
    const comp = r === null ? 70 : r <= 3 ? 100 : r <= 10 ? 70 : 40;          // unknown replies (mail source) = 70
    const text = row.title + '\n' + row.body_text;
    const budget = PAID_TRIAL.test(text) || (row.__rate_usd !== null && (MIN_RATE === null || row.__rate_usd >= MIN_RATE)) ? 100 : 50;
    const remote = row.remote_hint ? 100 : 60;
    const bonus = BONUS.test(text) ? 10 : 0;
    const total = Math.max(0, Math.min(100, Math.round(0.35 * stack + 0.20 * intent + 0.15 * fresh + 0.15 * comp + 0.10 * budget + 0.05 * remote + bonus)));
    row.gig_score = total;
    row.score_breakdown = `stack=${stack} intent=${intent} fresh=${fresh} comp=${comp} budget=${budget} remote=${remote} bonus=${bonus} -> ${total}`;
    scored++;
  } else {
    row.gig_score = null;
    row.score_breakdown = '';
  }
  for (const k of Object.keys(row)) if (k.startsWith('__')) delete row[k];
  return row;
});
stats.scored = scored;

const on = G.enabled !== false && T.enabled !== false;
const minScore = Number(G.min_score ?? 60);
const maxAge = Number(G.max_age_hours ?? 72);
const maxDrafts = on ? Math.max(0, Math.min(20, Number(G.max_drafts_per_run ?? 2))) : 0;

return [{ json: {
  posts: packed,
  stats,
  source_notes: notes,
  draft_params: [minScore, maxAge, maxDrafts],
  expire_hours: Math.max(1, maxAge * 2),
  enabled: on
} }];

// Draft Gig Reply (Code node, Run Once for All Items). Sprint 15.
// Drafts a short reply for each post from Select Gigs to Draft, validated by fixed rules (gig validator), one repair
// retry per provider, then needs_redraft. The LLM router section is copied verbatim from Draft Outreach (ADR-115):
// keep both in sync until an LLM Router sub-workflow exists. Nothing is sent: drafts go to the review console.
const cfg = $('Load Config').first().json.config || {};
const O = cfg.outreach || {};
const L = O.llm || {};

// ---------- settings (all overridable from config.outreach.llm) ----------
const T0 = Date.now();
const TIMEOUT = Math.max(5000, Number(L.timeout_ms || 40000));
const TEMP = Number(L.temperature ?? 0.3);
const PACE_MS = Math.max(0, Number(L.politeness_ms ?? 6000));          // pause between drafts
const MAX_OUT = Math.max(600, Number(L.max_output_tokens || 1500));    // includes reasoning tokens
const MAX_WAIT_S = Math.max(0, Number(L.max_wait_s ?? 20));            // longest single wait on a 429
let WAIT_BUDGET_MS = Math.max(0, Number(L.wait_budget_ms ?? 90000));   // total 429 waiting per run
const RUN_BUDGET_MS = Math.max(60000, Number(L.run_budget_ms || 240000)); // stay under the Code node time limit
const SITE = Object.assign({ enabled: true, timeout_ms: 8000 }, O.site_facts || {});

const SENDER = String(O.sender_name || 'Mohamed');
const CTA = String(O.cta || 'Open to a 2-minute workflow example relevant to your stack?');
const PROOFS = (O.proof_points && O.proof_points.length) ? O.proof_points : ['Built a federated B2B GTM SaaS platform with FastAPI, Supabase and LLM routing'];
const WATCH = (O.tool_watchlist || ['hubspot','salesforce','pipedrive','shopify','stripe','intercom','calendly','google analytics','zapier','slack','mixpanel','snowflake','zendesk','marketo','salesloft','airtable']).map(s => String(s).toLowerCase());
const W = { total: [Number((O.words || {}).min || 70), Number((O.words || {}).max || 120)], note: [20, 40] };
const NOTES_MAX = 600;   // risk_notes length. Sprint 14 adds 5 flags, so the cap went from 450 to 600 to keep the llm_errors readable.

const sleep = ms => new Promise(r => setTimeout(r, ms));
const wc = s => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const norm = s => String(s == null ? '' : s).replace(/[‐‑‒–]/g, '-').replace(/\s*—\s*/g, ' - ').replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/\s+\n/g, '\n').replace(/[ ]{2,}/g, ' ').trim();
const has = (hay, needle) => new RegExp('(^|[^a-z0-9])' + needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)', 'i').test(hay);

// ---------- provider registry ----------
// Every provider except Gemini speaks the OpenAI chat format, so adding one is a line of config, not new code.
const PRESETS = {
  groq:       { kind: 'openai', url: 'https://api.groq.com/openai/v1/chat/completions', key: 'GROQ_API_KEY',       model: L.groq_model || 'openai/gpt-oss-120b' },
  mistral:    { kind: 'openai', url: 'https://api.mistral.ai/v1/chat/completions',      key: 'MISTRAL_API_KEY',    model: L.mistral_model || 'mistral-small-latest' },
  cerebras:   { kind: 'openai', url: 'https://api.cerebras.ai/v1/chat/completions',     key: 'CEREBRAS_API_KEY',   model: L.cerebras_model || 'gpt-oss-120b' },
  openrouter: { kind: 'openai', url: 'https://openrouter.ai/api/v1/chat/completions',   key: 'OPENROUTER_API_KEY', model: L.openrouter_model || '' },
  gemini:     { kind: 'gemini', url: 'https://generativelanguage.googleapis.com/v1beta/models/', key: 'GEMINI_API_KEY', model: L.gemini_model || 'gemini-3.8-flash' }
};
// Optional extra providers from config: outreach.llm.providers = { "name": { "url": "...", "key_env": "NAME_API_KEY", "model": "..." } }
for (const [name, p] of Object.entries(L.providers || {})) {
  if (p && p.url && p.key_env) PRESETS[String(name).toLowerCase()] = { kind: p.kind === 'gemini' ? 'gemini' : 'openai', url: String(p.url), key: String(p.key_env), model: String(p.model || '') };
}

// A chain entry is "provider" or "provider:model". The second form lets one key use two models,
// and each model has its own rate limit bucket.
const parseStep = (entry) => {
  const s = String(entry || '').trim();
  const i = s.indexOf(':');
  const name = (i === -1 ? s : s.slice(0, i)).toLowerCase();
  const preset = PRESETS[name];
  if (!preset) return { id: s, error: 'unknown' };
  const model = i === -1 ? preset.model : s.slice(i + 1).trim();
  if (!model) return { id: s, error: 'no_model' };
  return { id: i === -1 ? name : name + ':' + model, name, model, kind: preset.kind, url: preset.url, key: preset.key };
};
const CHAIN = (Array.isArray(L.chain) && L.chain.length ? L.chain : ['groq', 'gemini', 'template'])
  .filter(s => String(s).toLowerCase() !== 'template').map(parseStep);

// Per-model extras that cut token use. If a provider rejects them (HTTP 400), the call is retried once without them.
const extrasFor = (step) => {
  const m = step.model.toLowerCase();
  const x = {};
  if (step.name === 'mistral') x.max_tokens = MAX_OUT; else x.max_completion_tokens = MAX_OUT;
  if (m.includes('gpt-oss')) { x.reasoning_effort = 'low'; if (step.name === 'groq') x.include_reasoning = false; }
  else if (m.includes('qwen')) { x.reasoning_effort = 'low'; if (step.name === 'groq') x.reasoning_format = 'hidden'; }
  return x;
};

// One HTTP call that never throws. Returns { status, headers, body, err }.
const http = async (opts) => {
  try {
    const res = await this.helpers.httpRequest(Object.assign({ json: true, timeout: TIMEOUT, returnFullResponse: true, ignoreHttpStatusErrors: true }, opts));
    if (res && typeof res === 'object' && ('statusCode' in res || 'status' in res) && 'body' in res) {
      let body = res.body;
      if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep text */ } }
      return { status: Number(res.statusCode || res.status || 0), headers: res.headers || {}, body, err: '' };
    }
    return { status: 200, headers: {}, body: res, err: '' };   // helper returned the body directly
  } catch (e) {
    const msg = String((e && e.message) || e);
    const m = msg.match(/status code (\d{3})/i);
    const r = (e && e.response) || {};
    return { status: m ? Number(m[1]) : Number(r.status || e.httpCode || 0), headers: r.headers || {}, body: r.data || r.body || null, err: msg };
  }
};
const header = (h, name) => { const k = Object.keys(h || {}).find(x => x.toLowerCase() === name); return k ? h[k] : undefined; };
const errText = (body) => {
  if (!body) return '';
  if (typeof body === 'string') return body.slice(0, 120);
  const e = body.error || body;
  return String((e && (e.message || e.code || e.status)) || '').slice(0, 120);
};
// Seconds to wait after a 429: the retry-after header, else "try again in 7.6s" from the message, else 30.
const retryAfter = (r) => {
  const h = Number(header(r.headers, 'retry-after'));
  if (Number.isFinite(h) && h > 0) return h;
  const m = (errText(r.body) + ' ' + r.err).match(/(?:try again|retry) in\s+(?:(\d+)m)?\s*([\d.]+)\s*s/i);
  if (m) return Number(m[1] || 0) * 60 + Number(m[2]);
  return 30;
};

const parseJSON = text => {
  const t = String(text || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  if (s === -1 || e <= s) return null;
  try { return JSON.parse(t.slice(s, e + 1)); } catch (err) { return null; }
};

const noExtras = {};   // step id -> true once a provider has rejected the extras
const callStep = async (step, system, user) => {
  const KEY = $env[step.key];
  if (step.kind === 'gemini') {
    const r = await http({ method: 'POST', url: step.url + step.model + ':generateContent',
      headers: { 'Content-Type': 'application/json', 'x-goog-api-key': KEY },
      body: { systemInstruction: { parts: [{ text: system }] }, contents: [{ role: 'user', parts: [{ text: user }] }],
              generationConfig: { temperature: TEMP, responseMimeType: 'application/json' } } });
    if (r.status === 200) r.text = (((r.body || {}).candidates || [])[0]?.content?.parts || []).map(x => x.text || '').join('');
    return r;
  }
  const base = { model: step.model, temperature: TEMP, response_format: { type: 'json_object' },
                 messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };
  const send = (body) => http({ method: 'POST', url: step.url, headers: { Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' }, body });
  let r = await send(noExtras[step.id] ? base : Object.assign({}, base, extrasFor(step)));
  if (r.status === 400 && !noExtras[step.id]) { noExtras[step.id] = true; r = await send(base); r.retried_plain = true; }
  if (r.status === 200) r.text = ((r.body || {}).choices || [])[0]?.message?.content;
  return r;
};

